action.command:
cd /workspace; cat > /tmp/fp_test2.php <<'PHP'
<?php
require '/var/www/html/vendor/autoload.php';
require '/var/www/html/config/web.config.php';
require '/var/www/html/config/web.config.local.php';
Dsl\App\Page::$config = array_replace_recursive($config, $configLocal);
use Dsl\App\Entities\FachPlanung;
use Dsl\App\Entities\GesamtPlan;
$p2024 = GesamtPlan::getGesamtPlan(2024);
$db = Dsl\App\Page::db();
$db->beginTransaction();
$r = FachPlanung::addFachPlanung('9901', $p2024);
echo "addFachPlanung 9901 -> 2024 result: " . strip_tags($r) . "\n";
$db->rollBack();
PHP
docker cp /tmp/fp_test2.php ddev-tfm-fachplanung-web:/tmp/fp_test2.php
docker exec ddev-tfm-fachplanung-web bash -c 'cd /var/www/html && php -dxdebug.mode=off /tmp/fp_test2.php' 2>&1 | tail -10

